ref = [1,2,3,4,1,2,5,1,2,3,4,5]

def fifo(ref, n):
    q = []
    faults = 0
    for p in ref:
        if p in q:
            continue
        faults += 1
        if len(q) < n:
            q.append(p)
        else:
            q.pop(0)
            q.append(p)
    return faults

def lru(ref, n):
    frames = []
    faults = 0
    for p in ref:
        if p in frames:
            frames.remove(p)
            frames.append(p)
        else:
            faults += 1
            if len(frames) < n:
                frames.append(p)
            else:
                frames.pop(0)
                frames.append(p)
    return faults

def opt(ref, n):
    frames = []
    faults = 0
    for i, p in enumerate(ref):
        if p in frames:
            continue
        faults += 1
        if len(frames) < n:
            frames.append(p)
        else:
            farthest = -1
            victim = 0
            for j, f in enumerate(frames):
                try:
                    nxt = ref.index(f, i + 1)
                except ValueError:
                    nxt = 10**9
                if nxt > farthest:
                    farthest = nxt
                    victim = j
            frames[victim] = p
    return faults

print(fifo(ref, 3))
print(lru(ref, 3))
print(opt(ref, 3))
